<?php require __DIR__.'/bootstrap.php';$method=$_SERVER['REQUEST_METHOD']??'GET';messenger_run(function($u)use($method){if($method==='GET'){$cid=(int)($_GET['conversation_id']??0);MessengerSecurity::participant($cid,(int)$u['id']);return Database::fetchAll('SELECT p.user_id,p.participant_role,p.can_send,p.is_muted,p.last_read_at,u.name,u.department,u.role_key FROM chat_participants p JOIN users u ON u.id=p.user_id WHERE p.conversation_id=? AND p.deleted_at IS NULL AND p.left_at IS NULL ORDER BY p.participant_role,u.name',[$cid]);}$in=messenger_input();MessengerService::participantAction((int)($in['conversation_id']??0),(int)($in['user_id']??$u['id']),$in,$u);return ['updated'=>true];},$method!=='GET');
